std::vector<unsigned char> Images::http(const std::string& url,size_t limit){
    auto text=wide(url);URL_COMPONENTS parts{};parts.dwStructSize=sizeof(parts);parts.dwHostNameLength=parts.dwUrlPathLength=parts.dwExtraInfoLength=DWORD(-1);
    if(!WinHttpCrackUrl(text.c_str(),DWORD(text.size()),0,&parts)||parts.nScheme!=INTERNET_SCHEME_HTTP)throw std::runtime_error("Invalid cover URL");
    std::wstring host(parts.lpszHostName,parts.dwHostNameLength);if(host!=L"127.0.0.1")throw std::runtime_error("Covers must use the protected local proxy");
    std::wstring route(parts.lpszUrlPath,parts.dwUrlPathLength);if(parts.dwExtraInfoLength)route.append(parts.lpszExtraInfo,parts.dwExtraInfoLength);
    Internet session{WinHttpOpen(L"RhineMusicD3D/0.3",WINHTTP_ACCESS_TYPE_NO_PROXY,nullptr,nullptr,0)};if(!session.handle)throw std::runtime_error("Cover session failed");WinHttpSetTimeouts(session.handle,3000,3000,5000,10000);
    Internet connection{WinHttpConnect(session.handle,host.c_str(),parts.nPort,0)},request{WinHttpOpenRequest(connection.handle,L"GET",route.c_str(),nullptr,nullptr,nullptr,0)};
    DWORD policy=WINHTTP_OPTION_REDIRECT_POLICY_NEVER;WinHttpSetOption(request.handle,WINHTTP_OPTION_REDIRECT_POLICY,&policy,sizeof(policy));
    if(!request.handle||!WinHttpSendRequest(request.handle,nullptr,0,nullptr,0,0,0)||!WinHttpReceiveResponse(request.handle,nullptr))throw std::runtime_error("Cover request failed");
    DWORD status=0,length=sizeof(status);if(!WinHttpQueryHeaders(request.handle,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,nullptr,&status,&length,nullptr))throw std::runtime_error("Cover response headers unavailable");if(status!=200)throw std::runtime_error("Cover HTTP status "+std::to_string(status));
    std::vector<unsigned char> bytes;unsigned char buffer[32768];DWORD read=0;for(;;){if(!WinHttpReadData(request.handle,buffer,sizeof(buffer),&read))throw std::runtime_error("Cover read failed");if(!read)break;if(bytes.size()+read>limit)throw std::runtime_error("Cover exceeds size limit");bytes.insert(bytes.end(),buffer,buffer+read);}return bytes;
}
static std::shared_ptr<Pixels> decode(const std::vector<unsigned char>& bytes,IWICImagingFactory* factory){
    if(bytes.empty())throw std::runtime_error("Empty image");Com<IWICStream> stream;check(factory->CreateStream(&stream),"WIC stream");check(stream->InitializeFromMemory(const_cast<BYTE*>(bytes.data()),DWORD(bytes.size())),"WIC memory");Com<IWICBitmapDecoder> decoder;check(factory->CreateDecoderFromStream(stream.Get(),nullptr,WICDecodeMetadataCacheOnLoad,&decoder),"WIC decoder");Com<IWICBitmapFrameDecode> frame;check(decoder->GetFrame(0,&frame),"WIC frame");UINT width=0,height=0;check(frame->GetSize(&width,&height),"Cover dimensions");if(!width||!height||uint64_t(width)*height>32'000'000)throw std::runtime_error("Cover dimensions exceed limit");
    Com<IWICBitmapSource> source=frame;double ratio=std::min(1.,1024./std::max(width,height));if(ratio<1){Com<IWICBitmapScaler> scale;check(factory->CreateBitmapScaler(&scale),"WIC scaler");width=std::max(1u,UINT(std::round(width*ratio)));height=std::max(1u,UINT(std::round(height*ratio)));check(scale->Initialize(frame.Get(),width,height,WICBitmapInterpolationModeFant),"Cover scale");source=scale;}
    Com<IWICFormatConverter> converter;check(factory->CreateFormatConverter(&converter),"WIC RGBA");check(converter->Initialize(source.Get(),GUID_WICPixelFormat32bppRGBA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom),"Cover conversion");auto result=std::make_shared<Pixels>();result->width=width;result->height=height;result->rgba.resize(size_t(width)*height*4);check(converter->CopyPixels(nullptr,width*4,UINT(result->rgba.size()),result->rgba.data()),"Cover pixels");return result;
}
static std::shared_ptr<Pixels> placeholder(IWICImagingFactory* factory,IDWriteFactory* write,IDWriteFontCollection* fonts,const std::string& title){
    constexpr UINT size=1024;Com<IWICBitmap> bitmap;check(factory->CreateBitmap(size,size,GUID_WICPixelFormat32bppPBGRA,WICBitmapCacheOnLoad,&bitmap),"Placeholder bitmap");Com<ID2D1Factory> d2d;check(D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED,d2d.GetAddressOf()),"Placeholder D2D");Com<ID2D1RenderTarget> target;check(d2d->CreateWicBitmapRenderTarget(bitmap.Get(),D2D1::RenderTargetProperties(),&target),"Placeholder target");Com<ID2D1SolidColorBrush> brush;check(target->CreateSolidColorBrush(D2D1::ColorF(.973f,.969f,.945f),&brush),"Placeholder brush");
    target->BeginDraw();target->Clear(D2D1::ColorF(.7882f,.7882f,.7686f));target->DrawEllipse(D2D1::Ellipse(D2D1::Point2F(size*.5f,size*.43f),size*.2f,size*.2f),brush.Get(),size*.003f);target->DrawEllipse(D2D1::Ellipse(D2D1::Point2F(size*.5f,size*.43f),size*.04f,size*.04f),brush.Get(),size*.003f);brush->SetColor(D2D1::ColorF(.247f,.282f,.286f));
    for(auto row:std::array<std::pair<std::wstring,float>,2>{{{wide(title),.80f},{L"LOCAL COLLECTION / NO COVER",.87f}}}){Com<IDWriteTextFormat> format;check(write->CreateTextFormat(L"MiSans",fonts,DWRITE_FONT_WEIGHT_NORMAL,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,size*(row.second==.8f?.045f:.025f),L"zh-CN",&format),"Placeholder font");format->SetTextAlignment(DWRITE_TEXT_ALIGNMENT_CENTER);format->SetWordWrapping(DWRITE_WORD_WRAPPING_NO_WRAP);target->DrawTextW(row.first.c_str(),UINT(row.first.size()),format.Get(),D2D1::RectF(size*.04f,size*row.second,size*.96f,size*(row.second+.1f)),brush.Get(),D2D1_DRAW_TEXT_OPTIONS_CLIP);}
    check(target->EndDraw(),"Placeholder draw");Com<IWICFormatConverter> converter;check(factory->CreateFormatConverter(&converter),"Placeholder RGBA");check(converter->Initialize(bitmap.Get(),GUID_WICPixelFormat32bppRGBA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom),"Placeholder conversion");auto result=std::make_shared<Pixels>();result->width=result->height=size;result->rgba.resize(size*size*4);check(converter->CopyPixels(nullptr,size*4,UINT(result->rgba.size()),result->rgba.data()),"Placeholder pixels");return result;
}
