Images::Images(IDWriteFactory* write,IDWriteFontCollection* fonts):write_(write),fonts_(fonts){for(auto& thread:workers_)thread=std::thread([this]{run();});}
Images::~Images(){{std::lock_guard lock(mutex_);stop_=true;jobs_.clear();}cv_.notify_all();for(auto& thread:workers_)if(thread.joinable())thread.join();}
void Images::detachFonts(){{std::lock_guard lock(mutex_);stop_=true;}cv_.notify_all();for(auto& thread:workers_)if(thread.joinable())thread.join();write_.Reset();fonts_.Reset();}
void Images::rebindFonts(IDWriteFactory* write,IDWriteFontCollection* fonts){write_=write;fonts_=fonts;{std::lock_guard lock(mutex_);stop_=false;}for(auto& thread:workers_)thread=std::thread([this]{run();});}
std::shared_ptr<Pixels> Images::get(const std::string& key,const std::string& url,const std::string& title){const std::string sharedKey=url.empty()?key:"url:"+url;std::lock_guard lock(mutex_);auto& entry=cache_[sharedKey];entry.used=++clock_;if(!entry.pixels&&!entry.loading){entry.loading=true;jobs_.push_back({sharedKey,url,title});cv_.notify_one();}return entry.pixels;}
json Images::status(){std::lock_guard lock(mutex_);size_t bytes=0,ready=0,loading=0,failed=0;json failures=json::array();for(const auto& [key,value]:cache_){loading+=value.loading;failed+=value.failed;if(value.failed)failures.push_back({{"request",key},{"error",value.failure}});if(auto p=value.pixels){++ready;bytes+=p->rgba.size()+(p->thumbnail?p->thumbnail->rgba.size():0)+(p->square?p->square->rgba.size():0);}}return {{"failedEntries",failed},{"failures",failures},{"decodedBytes",bytes},{"readyEntries",ready},{"loadingEntries",loading},{"queuedRequests",jobs_.size()},{"budgetBytes",128*1024*1024},{"sharedRequests",true}};}
bool Images::retryFailed(){std::lock_guard lock(mutex_);bool changed=false;for(auto it=cache_.begin();it!=cache_.end();)if(it->second.failed&&!it->second.loading){it=cache_.erase(it);changed=true;}else ++it;return changed;}
void Images::run(){CoInitializeEx(nullptr,COINIT_MULTITHREADED);Com<IWICImagingFactory> factory;if(FAILED(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&factory)))){CoUninitialize();return;}for(;;){Job job;std::string origin;{std::unique_lock lock(mutex_);cv_.wait(lock,[this]{return stop_||!jobs_.empty();});if(stop_)break;job=std::move(jobs_.front());jobs_.pop_front();origin=origin_;}
    std::shared_ptr<Pixels> image;bool failed=false;std::string failure;try{image=job.url.empty()?(job.title.starts_with("archive-label:")?archiveLabel(factory.Get(),write_.Get(),fonts_.Get(),job.title):job.title.starts_with("cd-disc:")?compactDisc(factory.Get(),write_.Get(),fonts_.Get()):placeholder(factory.Get(),write_.Get(),fonts_.Get(),job.title)):decode(http(origin+job.url),factory.Get());}catch(const std::exception& error){failed=!job.url.empty();failure=error.what();try{image=placeholder(factory.Get(),write_.Get(),fonts_.Get(),job.title);}catch(...){}}catch(...){failed=!job.url.empty();failure="Unknown image decoding error";try{image=placeholder(factory.Get(),write_.Get(),fonts_.Get(),job.title);}catch(...){}}
    if(image){image->thumbnail=tile(*image,256);image->square=tile(*image,1024);}
    {std::lock_guard lock(mutex_);auto& entry=cache_[job.key];entry.pixels=std::move(image);entry.loading=false;entry.failed=failed;entry.failure=std::move(failure);if(entry.pixels)entry.pixels->serial=++serial_;
        auto footprint=[](const std::shared_ptr<Pixels>& p){return p?p->rgba.size()+(p->thumbnail?p->thumbnail->rgba.size():0)+(p->square?p->square->rgba.size():0):size_t(0);};size_t bytes=0;for(auto& item:cache_)bytes+=footprint(item.second.pixels);while(bytes>128*1024*1024&&cache_.size()>1){auto oldest=cache_.end();for(auto it=cache_.begin();it!=cache_.end();++it)if(it->first!=job.key&&!it->second.loading&&it->second.pixels&&it->second.pixels.use_count()==1&&(oldest==cache_.end()||it->second.used<oldest->second.used))oldest=it;if(oldest==cache_.end())break;bytes-=footprint(oldest->second.pixels);cache_.erase(oldest);}}
    }factory.Reset();CoUninitialize();
}
std::shared_ptr<Pixels> Images::tile(const Pixels& source,unsigned size){auto result=std::make_shared<Pixels>();result->width=result->height=size;result->serial=source.serial;result->rgba.resize(size_t(size)*size*4,0);
    unsigned padding=std::max(1u,size/128),available=size-padding*2;double ratio=double(available)/std::max(source.width,source.height);unsigned width=std::max(1u,unsigned(std::round(source.width*ratio))),height=std::max(1u,unsigned(std::round(source.height*ratio))),left=(size-width)/2,top=(size-height)/2;
    for(unsigned y=0;y<height;++y)for(unsigned x=0;x<width;++x){float px=(x+.5f)*source.width/width-.5f,py=(y+.5f)*source.height/height-.5f;int sx=int(std::floor(px)),sy=int(std::floor(py));float fx=px-sx,fy=py-sy;for(unsigned channel=0;channel<4;++channel){auto sample=[&](int dx,int dy){return source.rgba[(size_t(std::clamp(sy+dy,0,int(source.height)-1))*source.width+std::clamp(sx+dx,0,int(source.width)-1))*4+channel];};float value=std::lerp(std::lerp(float(sample(0,0)),float(sample(1,0)),fx),std::lerp(float(sample(0,1)),float(sample(1,1)),fx),fy);result->rgba[(size_t(y+top)*size+x+left)*4+channel]=static_cast<unsigned char>(std::clamp(value,0.f,255.f));}}
    return result;
}
